variables.low_batteries:
{% set excluded = ['sensor.entity_020','sensor.entity_018','sensor.entity_002','sensor.entity_021','sensor.entity_017','sensor.entity_022','sensor.entity_004','sensor.entity_001'] %}
{% set ns = namespace(items=[]) %}
{% for s in states.sensor | selectattr('attributes.device_class','defined') | selectattr('attributes.device_class','eq','battery') %}
  {% if s.entity_id not in excluded and s.state not in ['unknown','unavailable'] and (s.state | float(101)) <= 20 %}
    {% set ns.items = ns.items + [s.name ~ ' @ ' ~ s.state ~ '%'] %}
  {% endif %}
{% endfor %}
{% for s in states.binary_sensor | selectattr('attributes.device_class','defined') | selectattr('attributes.device_class','eq','battery') %}
  {% if s.entity_id not in excluded and s.state in ['on','low'] %}
    {% set ns.items = ns.items + [s.name ~ ' is low'] %}
  {% endif %}
{% endfor %}
{{ ns.items | sort | join('\n') }}
